1|// One scene view: heading, reading column, pictures, vault, pager.
2|// Sub-page moves stay in client state; scene moves push a new route.
3|"use client";
4|
5|import { Fragment, useEffect, useMemo, useRef, useState } from "react";
6|import { useRouter } from "next/navigation";
7|import { buildNavIndex, navReducer } from "@/core/reader";
8|import type { NavAction, SceneView } from "@/core/reader";
9|import { loadImageStylePref, saveImageStylePref } from "../image-style";
10|import type { ImageStylePref } from "../image-style";
11|import { BandPager, Divider } from "../folio/chrome";
12|import { ImagePane } from "../folio/image-pane";
13|import { InlineFigureView, SelectionPopover } from "../folio/inline-figures";
14|import { Lightbox } from "../folio/lightbox";
15|import { usePictures } from "../folio/use-pictures";
16|import type { InlineFigure } from "../folio/use-pictures";
17|import { PictureVault } from "../folio/vault";
18|
19|// One-shot entry intent: set just before pushing the previous scene
20|// route, so the new page opens on its last sub-page. Client memory only,
21|// never the URL, so prerendered pages stay static and a direct URL load
22|// always starts at page 0.
23|let enterAtEnd = false;
24|
25|// Set on every in-app scene push. The heading takes focus only when this
26|// is set, so first load shows no focus ring.
27|let hasNavigated = false;
28|
29|function pulse(el: HTMLElement | null) {
30|  if (!el) return;
31|  el.classList.remove("pulse");
32|  void el.offsetWidth;
33|  el.classList.add("pulse");
34|  window.setTimeout(() => el.classList.remove("pulse"), 650);
35|}
36|
37|// One scene view: sub-pages, keys, buttons, progress, chapter jump.
38|// Sub-page moves stay in client state; scene moves push a new route.
39|export function ScenePage({
40|  view,
41|  views,
42|  bookId,
43|  textVersion,
44|  bookIndex,
45|  bookTotal,
46|}: {
47|  view: SceneView;
48|  views: { sceneId: string; pages: number }[];
49|  bookId: string;
50|  textVersion: string;
51|  bookIndex: number;
52|  bookTotal: number;
53|}) {
54|  const pic = usePictures({ bookId, textVersion, sceneId: view.sceneId });
55|  const [pref, setPref] = useState<ImageStylePref>({ kind: "preset", id: "denslow" });
56|  const router = useRouter();
57|  const index = useMemo(() => buildNavIndex(views), [views]);
58|  const lastPage = view.pages.length - 1;
59|  const [page, setPage] = useState(() => {
60|    if (enterAtEnd) {
61|      enterAtEnd = false;
62|      return lastPage;
63|    }
64|    return 0;
65|  });
66|  const headingRef = useRef<HTMLHeadingElement>(null);
67|  const readColRef = useRef<HTMLDivElement | null>(null);
68|  const figEls = useRef(new Map<string, HTMLElement>());
69|  const sub = view.pages[page] ?? view.pages[0];
70|  const atStart = view.prevSceneId === null && page === 0;
71|  const atBookEnd = view.nextSceneId === null && page === lastPage;
72|
73|  useEffect(() => {
74|    setPref(loadImageStylePref());
75|  }, []);
76|
77|  function changePref(next: ImageStylePref) {
78|    setPref(next);
79|    saveImageStylePref(next);
80|  }
81|
82|  const figsByN = useMemo(() => {
83|    const grouped = new Map<number, InlineFigure[]>();
84|    for (const fig of pic.figures) {
85|      const list = grouped.get(fig.endN) ?? [];
86|      list.push(fig);
87|      grouped.set(fig.endN, list);
88|    }
89|    return grouped;
90|  }, [pic.figures]);
91|
92|  function pageOf(n: number): number {
93|    const found = view.pages.findIndex((p) => p.paragraphs.some((para) => para.n === n));
94|    return found;
95|  }
96|
97|  function gotoFigure(fig: InlineFigure) {
98|    const at = pageOf(fig.endN);
99|    if (at < 0) return;
100|    setPage(at);
101|    readColRef.current?.scrollTo(0, 0);
102|    requestAnimationFrame(() => {
103|      requestAnimationFrame(() => {
104|        const el = figEls.current.get(fig.id) ?? null;
105|        el?.scrollIntoView({ block: "nearest" });
106|        pulse(el);
107|      });
108|    });
109|  }
110|
111|  function gotoScenePicture() {
112|    const img = document.querySelector(".img-pane .pane-img");
113|    pulse(img instanceof HTMLElement ? img : null);
114|  }
115|
116|  // Every pager move runs through navReducer; a new scene id means a
117|  // route push, a same-scene result means a client sub-page move.
118|  function move(action: NavAction) {
119|    pic.hidePopover();
120|    const next = navReducer({ sceneId: view.sceneId, page }, action, index);
121|    if (next.sceneId !== view.sceneId) {
122|      hasNavigated = true;
123|      if (next.page > 0) enterAtEnd = true;
124|      router.push(`/leer/${next.sceneId}`);
125|      return;
126|    }
127|    if (next.page !== page) {
128|      setPage(next.page);
129|      readColRef.current?.scrollTo(0, 0);
130|    }
131|  }
132|
133|  function goNext() {
134|    move({ kind: "next" });
135|  }
136|
137|  function goPrev() {
138|    move({ kind: "prev" });
139|  }
140|
141|  // Scene entry resets orientation; sub-page moves keep the heading.
142|  useEffect(() => {
143|    if (hasNavigated) headingRef.current?.focus();
144|    readColRef.current?.scrollTo(0, 0);
145|  }, [view.sceneId]);
146|
147|  useEffect(() => {
148|    const onKey = (event: KeyboardEvent) => {
149|      if (event.metaKey || event.ctrlKey || event.altKey) return;
150|      const target = event.target as HTMLElement | null;
151|      if (
152|        target &&
153|        (target.tagName === "INPUT" ||
154|          target.tagName === "SELECT" ||
155|          target.tagName === "TEXTAREA" ||
156|          target.isContentEditable)
157|      ) {
158|        return;
159|      }
160|      if (event.key === "ArrowRight") {
161|        event.preventDefault();
162|        goNext();
163|      } else if (event.key === "ArrowLeft") {
164|        event.preventDefault();
165|        goPrev();
166|      }
167|    };
168|    window.addEventListener("keydown", onKey);
169|    return () => window.removeEventListener("keydown", onKey);
170|  }, [page, view.sceneId, index, router]);
171|
172|  return (
173|    <>
174|      <ImagePane
175|        card={pic.card}
176|        onPicture={() => pic.illustrateScene(pref)}
177|        onRetry={() => pic.illustrateScene(pref)}
178|        onClear={pic.clearScene}
179|        onOpen={pic.openLightbox}
180|      />
181|      <Divider />
182|      <div className="read-col" ref={readColRef} aria-label="Reading column">
183|        <div className="kicker">Chapter {view.ch}</div>
184|        <h1 className="chapter-title" id="scene-heading" ref={headingRef} tabIndex={-1}>
185|          {view.chapterTitle}
186|        </h1>
187|        <div className="scene-line">
188|          <span>
189|            Scene {view.k} of {view.n}
190|            {view.pages.length > 1 ? ` · Page ${page + 1} of ${view.pages.length}` : ""}
191|          </span>
192|        </div>
193|        <div
194|          className={`body-text${page === 0 ? " dropcap" : ""}`}
195|          ref={pic.viewRef}
196|        >
197|          {sub?.paragraphs.map((p) => (
198|            <Fragment key={p.id}>
199|              <p id={p.id} data-n={p.n}>
200|                {p.text}
201|              </p>
202|              {(figsByN.get(p.n) ?? []).map((fig) => (
203|                <InlineFigureView
204|                  key={fig.id}
205|                  figure={fig}
206|                  onRemove={() => pic.removeFigure(fig.id)}
207|                  onRetry={() => pic.retryFigure(fig.id, pref)}
208|                  onOpen={pic.openLightbox}
209|                  refCb={(el) => {
210|                    if (el) figEls.current.set(fig.id, el);
211|                    else figEls.current.delete(fig.id);
212|                  }}
213|                />
214|              ))}
215|            </Fragment>
216|          ))}
217|          {pic.popover !== null ? (
218|            <SelectionPopover
219|              pos={pic.popover}
220|              popRef={pic.popRef}
221|              onPick={() => pic.illustratePassage(pref)}
222|            />
223|          ) : null}
224|        </div>
225|      </div>
226|      <PictureVault
227|        scene={pic.card.phase === "ready" ? { url: pic.card.url, caption: pic.card.caption } : null}
228|        figures={pic.figures}
229|        onGotoScene={gotoScenePicture}
230|        onGotoFigure={gotoFigure}
231|        onOpen={pic.openLightbox}
232|        pref={pref}
233|        onPrefChange={changePref}
234|      />
235|      <BandPager
236|        k={view.k}
237|        n={view.n}
238|        bookIndex={bookIndex}
239|        bookTotal={bookTotal}
240|        onPrev={goPrev}
241|        onNext={goNext}
242|        atStart={atStart}
243|        atBookEnd={atBookEnd}
244|      />
245|      <Lightbox item={pic.lightbox} onClose={pic.closeLightbox} />
246|    </>
247|  );
