3|"use client";
4|
5|import { Fragment, useEffect, useMemo, useRef, useState } from "react";
6|import { useRouter } from "next/navigation";
7|import { buildNavIndex, navReducer } from "@/core/reader";
8|import type { NavAction, SceneView } from "@/core/reader";
9|import { loadImageStylePref, saveImageStylePref } from "../image-style";
10|import type { ImageStylePref } from "../image-style";
11|import { BandPager, Divider } from "../folio/chrome";
12|import { ImagePane } from "../folio/image-pane";
13|import { InlineFigureView, SelectionPopover } from "../folio/inline-figures";
14|import { Lightbox } from "../folio/lightbox";
15|import { usePictures } from "../folio/use-pictures";
16|import type { InlineFigure } from "../folio/use-pictures";
17|import { PictureVault } from "../folio/vault";
