19|// One-shot entry intent: set just before pushing the previous scene
20|// route, so the new page opens on its last sub-page. Client memory only,
21|// never the URL, so prerendered pages stay static and a direct URL load
22|// always starts at page 0.
23|let enterAtEnd = false;
24|
25|// Set on every in-app scene push. The heading takes focus only when this
26|// is set, so first load shows no focus ring.
27|let hasNavigated = false;
28|
29|function pulse(el: HTMLElement | null) {
30|  if (!el) return;
31|  el.classList.remove("pulse");
32|  void el.offsetWidth;
33|  el.classList.add("pulse");
34|  window.setTimeout(() => el.classList.remove("pulse"), 650);
35|}
