37|// One scene view: sub-pages, keys, buttons, progress, chapter jump.
38|// Sub-page moves stay in client state; scene moves push a new route.
39|export function ScenePage({
40|  view,
41|  views,
42|  bookId,
43|  textVersion,
44|  bookIndex,
45|  bookTotal,
46|}: {
47|  view: SceneView;
48|  views: { sceneId: string; pages: number }[];
49|  bookId: string;
50|  textVersion: string;
51|  bookIndex: number;
52|  bookTotal: number;
53|}) {
54|  const pic = usePictures({ bookId, textVersion, sceneId: view.sceneId });
55|  const [pref, setPref] = useState<ImageStylePref>({ kind: "preset", id: "denslow" });
56|  const router = useRouter();
57|  const index = useMemo(() => buildNavIndex(views), [views]);
58|  const lastPage = view.pages.length - 1;
59|  const [page, setPage] = useState(() => {
60|    if (enterAtEnd) {
61|      enterAtEnd = false;
62|      return lastPage;
63|    }
64|    return 0;
65|  });
66|  const headingRef = useRef<HTMLHeadingElement>(null);
67|  const readColRef = useRef<HTMLDivElement | null>(null);
68|  const figEls = useRef(new Map<string, HTMLElement>());
69|  const sub = view.pages[page] ?? view.pages[0];
70|  const atStart = view.prevSceneId === null && page === 0;
71|  const atBookEnd = view.nextSceneId === null && page === lastPage;
72|
73|  useEffect(() => {
74|    setPref(loadImageStylePref());
75|  }, []);
76|
77|  function changePref(next: ImageStylePref) {
78|    setPref(next);
79|    saveImageStylePref(next);
80|  }
81|
82|  const figsByN = useMemo(() => {
83|    const grouped = new Map<number, InlineFigure[]>();
84|    for (const fig of pic.figures) {
85|      const list = grouped.get(fig.endN) ?? [];
86|      list.push(fig);
87|      grouped.set(fig.endN, list);
88|    }
89|    return grouped;
90|  }, [pic.figures]);
91|
92|  function pageOf(n: number): number {
93|    const found = view.pages.findIndex((p) => p.paragraphs.some((para) => para.n === n));
94|    return found;
95|  }
96|
97|  function gotoFigure(fig: InlineFigure) {
98|    const at = pageOf(fig.endN);
99|    if (at < 0) return;
100|    setPage(at);
101|    readColRef.current?.scrollTo(0, 0);
102|    requestAnimationFrame(() => {
103|      requestAnimationFrame(() => {
104|        const el = figEls.current.get(fig.id) ?? null;
105|        el?.scrollIntoView({ block: "nearest" });
106|        pulse(el);
107|      });
108|    });
109|  }
