113|    pulse(img instanceof HTMLElement ? img : null);
114|  }
115|
116|  // Every pager move runs through navReducer; a new scene id means a
117|  // route push, a same-scene result means a client sub-page move.
118|  function move(action: NavAction) {
119|    pic.hidePopover();
120|    const next = navReducer({ sceneId: view.sceneId, page }, action, index);
121|    if (next.sceneId !== view.sceneId) {
122|      hasNavigated = true;
123|      if (next.page > 0) enterAtEnd = true;
124|      router.push(`/leer/${next.sceneId}`);
125|      return;
126|    }
127|    if (next.page !== page) {
128|      setPage(next.page);
129|      readColRef.current?.scrollTo(0, 0);
130|    }
131|  }
132|
133|  function goNext() {
134|    move({ kind: "next" });
135|  }
136|
137|  function goPrev() {
138|    move({ kind: "prev" });
139|  }
140|
141|  // Scene entry resets orientation; sub-page moves keep the heading.
142|  useEffect(() => {
143|    if (hasNavigated) headingRef.current?.focus();
144|    readColRef.current?.scrollTo(0, 0);
145|  }, [view.sceneId]);
146|
147|  useEffect(() => {
148|    const onKey = (event: KeyboardEvent) => {
149|      if (event.metaKey || event.ctrlKey || event.altKey) return;
150|      const target = event.target as HTMLElement | null;
