126|      aria-valuemin={SPLIT_MIN_PX}
127|      aria-valuemax={clampSplitWidth(Number.MAX_SAFE_INTEGER, viewport)}
128|      aria-valuenow={width}
129|      tabIndex={0}
130|      title="Drag to resize, double-click to reset"
131|      onDoubleClick={() => commit(defaultSplit())}
132|      onKeyDown={(e) => {
