1|// Drawing style preference: UI only until the /api/images style
2|// contract lands. Persisted in localStorage, parsed defensively.
3|export const IMAGE_STYLE_KEY = "lectoria.imageStyle";
4|
5|export type ImageStylePref = { kind: "preset"; id: string } | { kind: "custom"; text: string };
6|
7|export interface StylePreset {
8|  id: string;
9|  label: string;
10|}
11|
12|export const STYLE_PRESETS: StylePreset[] = [
13|  { id: "denslow", label: "Denslow ink (1900)" },
14|  { id: "watercolour", label: "Watercolour" },
15|  { id: "pencil", label: "Pencil sketch" },
16|  { id: "woodcut", label: "Woodcut" },
17|  { id: "gouache", label: "Storybook gouache" },
18|];
19|
20|export const DEFAULT_IMAGE_STYLE: ImageStylePref = { kind: "preset", id: "denslow" };
21|
22|export const DENSLOW_CREDIT = "In the style of W. W. Denslow";
23|
24|export function parseImageStylePref(json: unknown): ImageStylePref {
25|  if (typeof json === "object" && json !== null && !Array.isArray(json)) {
26|    const pref = json as Record<string, unknown>;
27|    if (pref.kind === "preset" && typeof pref.id === "string" && STYLE_PRESETS.some((p) => p.id === pref.id)) {
28|      return { kind: "preset", id: pref.id };
29|    }
30|    if (pref.kind === "custom" && typeof pref.text === "string" && pref.text.trim().length > 0) {
31|      return { kind: "custom", text: pref.text.trim().slice(0, 60) };
32|    }
33|  }
34|  return DEFAULT_IMAGE_STYLE;
35|}
36|
37|export function loadImageStylePref(): ImageStylePref {
38|  try {
39|    if (typeof window === "undefined") return DEFAULT_IMAGE_STYLE;
40|    const raw = window.localStorage.getItem(IMAGE_STYLE_KEY);
41|    if (!raw) return DEFAULT_IMAGE_STYLE;
42|    return parseImageStylePref(JSON.parse(raw));
43|  } catch {
44|    return DEFAULT_IMAGE_STYLE;
45|  }
46|}
47|
48|export function saveImageStylePref(pref: ImageStylePref): void {
49|  try {
50|    if (typeof window === "undefined") return;
51|    window.localStorage.setItem(IMAGE_STYLE_KEY, JSON.stringify(pref));
52|  } catch {
53|    // Private mode: new pictures use the default until reload.
54|  }
55|}
56|
57|// shortcut: style not sent until the /api/images style contract lands; wire it here
58|export function requestStyleFields(_pref: ImageStylePref): Record<string, never> {
59|  return {};
60|}
61|
62|// The credit never claims a style the request did not send.
63|export function styleCredit(fields: Record<string, never>): string {
64|  const sent = (fields as Record<string, unknown>).style;
65|  if (typeof sent === "string" && sent.length > 0) return sent;
66|  return DENSLOW_CREDIT;
67|}

